{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "language",
    "stack_name",
    "api_name",
    "allowed_origin",
    "account",
    "region"
  ],
  "properties": {
    "language": {
      "const": "javascript"
    },
    "stack_name": {
      "type": "string",
      "pattern": "^[A-Za-z][A-Za-z0-9-]{1,62}$"
    },
    "api_name": {
      "type": "string",
      "minLength": 1,
      "maxLength": 100
    },
    "allowed_origin": {
      "type": "string",
      "pattern": "^https://[A-Za-z0-9.-]+$"
    },
    "account": {
      "type": "string",
      "pattern": "^\\d{12}$"
    },
    "region": {
      "type": "string",
      "pattern": "^[a-z]{2}(-gov)?-[a-z]+-\\d$"
    }
  }
}

import { randomUUID } from 'node:crypto';
import { DynamoDBDocumentClient, PutCommand } from '@aws-sdk/lib-dynamodb';
import { DynamoDBClient } from '@aws-sdk/client-dynamodb';
import { reply } from './response.mjs';
const db = DynamoDBDocumentClient.from(new DynamoDBClient({}));
export const handler = async (event) => {
  const body = JSON.parse(event.body || '{}');
  if (!body || typeof body !== 'object' || Array.isArray(body) || typeof body.name !== 'string' || !body.name.trim()) {
    return reply(400, { error: 'name_required' });
  }
  const item = { id: randomUUID(), name: body.name.trim(), createdAt: new Date().toISOString() };
  await db.send(new PutCommand({ TableName: process.env.TABLE_NAME, Item: item, ConditionExpression: 'attribute_not_exists(id)' }));
  return reply(201, item);
};

import { DynamoDBDocumentClient, DeleteCommand } from '@aws-sdk/lib-dynamodb';
import { DynamoDBClient } from '@aws-sdk/client-dynamodb';
import { reply } from './response.mjs';
const db = DynamoDBDocumentClient.from(new DynamoDBClient({}));
export const handler = async (event) => {
  const id = event.pathParameters?.id;
  if (!id) return reply(400, { error: 'id_required' });
  try {
    await db.send(new DeleteCommand({ TableName: process.env.TABLE_NAME, Key: { id }, ConditionExpression: 'attribute_exists(id)' }));
    return { statusCode: 204, headers: { 'Access-Control-Allow-Origin': process.env.ALLOWED_ORIGIN, 'Vary': 'Origin' }, body: '' };
  } catch (error) {
    if (error.name === 'ConditionalCheckFailedException') return reply(404, { error: 'not_found' });
    throw error;
  }
};

import { DynamoDBDocumentClient, ScanCommand } from '@aws-sdk/lib-dynamodb';
import { DynamoDBClient } from '@aws-sdk/client-dynamodb';
import { reply } from './response.mjs';
const db = DynamoDBDocumentClient.from(new DynamoDBClient({}));
export const handler = async (event) => {
  const limit = Math.min(Math.max(Number(event.queryStringParameters?.limit) || 50, 1), 100);
  const result = await db.send(new ScanCommand({ TableName: process.env.TABLE_NAME, Limit: limit }));
  return reply(200, { items: result.Items || [], lastEvaluatedKey: result.LastEvaluatedKey || null });
};

import { DynamoDBDocumentClient, GetCommand } from '@aws-sdk/lib-dynamodb';
import { DynamoDBClient } from '@aws-sdk/client-dynamodb';
import { reply } from './response.mjs';
const db = DynamoDBDocumentClient.from(new DynamoDBClient({}));
export const handler = async (event) => {
  const id = event.pathParameters?.id;
  if (!id) return reply(400, { error: 'id_required' });
  const result = await db.send(new GetCommand({ TableName: process.env.TABLE_NAME, Key: { id } }));
  return result.Item ? reply(200, result.Item) : reply(404, { error: 'not_found' });
};

export function reply(statusCode, body) {
  return {
    statusCode,
    headers: {
      'Content-Type': 'application/json',
      'Access-Control-Allow-Origin': process.env.ALLOWED_ORIGIN,
      'Vary': 'Origin',
    },
    body: body === '' ? '' : JSON.stringify(body),
  };
}

import { DynamoDBDocumentClient, UpdateCommand } from '@aws-sdk/lib-dynamodb';
import { DynamoDBClient } from '@aws-sdk/client-dynamodb';
import { reply } from './response.mjs';
const db = DynamoDBDocumentClient.from(new DynamoDBClient({}));
export const handler = async (event) => {
  const id = event.pathParameters?.id;
  const body = JSON.parse(event.body || '{}');
  if (!id || typeof body.name !== 'string' || !body.name.trim()) return reply(400, { error: 'id_and_name_required' });
  try {
    const result = await db.send(new UpdateCommand({ TableName: process.env.TABLE_NAME, Key: { id }, UpdateExpression: 'SET #n = :n, updatedAt = :t', ConditionExpression: 'attribute_exists(id)', ExpressionAttributeNames: { '#n': 'name' }, ExpressionAttributeValues: { ':n': body.name.trim(), ':t': new Date().toISOString() }, ReturnValues: 'ALL_NEW' }));
    return reply(200, result.Attributes);
  } catch (error) {
    if (error.name === 'ConditionalCheckFailedException') return reply(404, { error: 'not_found' });
    throw error;
  }
};

