","mime_type":"application/json","path":"package.json","sha256":"051b3ef680873e284a55f6d24b2a93d3007334aae38cc55d5fa88b4f17bb8348","size_bytes":379},{"content":"import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { App } from 'aws-cdk-lib';
import { createStack } from './product.mjs';

// Trusted, private native Node preview. It synthesizes the actual product stack
// locally and returns only bounded counts; no CloudFormation template or AWS
// API call leaves this module. The gateway Worker currently cannot execute it.
export async function preview({ configuration, selected_components, prebuiltHandlers }) {
  let outdir;
  try {
    if (!Array.isArray(selected_components) || selected_components.length !== 1 || selected_components[0] !== 'stack') {
      return { ok: false, status: 'invalid', slug: 'api-gateway-lambda-dynamodb-stack', selected_components: [], resource_count: 0, diagnostic_codes: ['invalid_selection'] };
    }
    if (!configuration || configuration.language !== 'javascript') {
      return { ok: false, status: 'invalid', slug: 'api-gateway-lambda-dynamodb-stack', selected_components: ['stack'], resource_count: 0, diagnostic_codes: ['configuration_invalid'] };
    }
    outdir = mkdtempSync(join(tmpdir(), 'secondwind-private-cdk-preview-'));
    const app = new App({ outdir, analyticsReporting: false });
    createStack(app, { configuration, selected_components, prebuiltHandlers });
    const assembly = app.synth();
    const resource_count = assembly.stacks.reduce((sum, stack) => sum + Object.keys(stack.template?.Resources || {}).length, 0);
    return { ok: true, status: 'complete', slug: 'api-gateway-lambda-dynamodb-stack', selected_components: ['stack'], resource_count };
  } catch {
    return { ok: false, status: 'invalid', slug: 'api-gateway-lambda-dynamodb-stack', selected_components: ['stack'], resource_count: 0, diagnostic_codes: ['validation_failed'] };
  } finally {
    if (outdir) rmSync(outdir, { recursive: true, force: true });
  }
}
","mime_type":"text/javascript","path":"preview.mjs","sha256":"66609f7486e568bd376f70dd90bf9c56f8b6c20db747bdf8e5babb32a8c417fe","size_bytes":1908},{"content":"import { App, Stack, RemovalPolicy } from 'aws-cdk-lib';
import * as apigateway from 'aws-cdk-lib/aws-apigateway';
import * as dynamodb from 'aws-cdk-lib/aws-dynamodb';
import { NodejsFunction } from 'aws-cdk-lib/aws-lambda-nodejs';
import { Runtime, Code } from 'aws-cdk-lib/aws-lambda';
import { fileURLToPath } from 'node:url';

export function createStack(app, { configuration: c, prebuiltHandlers }) {
  if (!c || !/^https:\/\/[A-Za-z0-9.-]+$/.test(c.allowed_origin)
      || !/^[A-Za-z][A-Za-z0-9-]{1,62}$/.test(c.stack_name)
      || !/^\d{12}$/.test(c.account) || !c.region) throw new Error('invalid_configuration');
  const stack = new Stack(app, c.stack_name, { env: { account: c.account, region: c.region } });
  const table = new dynamodb.Table(stack, 'Items', {
    partitionKey: { name: 'id', type: dynamodb.AttributeType.STRING },
    billingMode: dynamodb.BillingMode.PAY_PER_REQUEST,
    removalPolicy: RemovalPolicy.RETAIN,
    pointInTimeRecovery: true,
  });
  const handler = (file, id) => new NodejsFunction(stack, id, {
    entry: fileURLToPath(new URL(`./handlers/${file}.mjs`, import.meta.url)),
    handler: prebuiltHandlers ? 'index.handler' : 'handler', runtime: Runtime.NODEJS_20_X,
    ...(prebuiltHandlers ? {code: Code.fromInline(prebuiltHandlers[file])} : {}),
    environment: { TABLE_NAME: table.tableName, ALLOWED_ORIGIN: c.allowed_origin },
    bundling: { minify: true, sourceMap: false },
  });
  const create = handler('create', 'CreateItem');
  const getOne = handler('get-one', 'GetItem');
  const getAll = handler('get-all', 'GetItems');
  const update = handler('update-one', 'UpdateItem');
  const remove = handler('delete-one', 'DeleteItem');
  table.grantWriteData(create);
  table.grantReadData(getOne);
  table.grantReadData(getAll);
  table.grantReadWriteData(update);
  table.grantReadWriteData(remove);
  const api = new apigateway.RestApi(stack, 'ItemsApi', {
    restApiName: c.api_name,
    defaultCorsPreflightOptions: {
      allowOrigins: [c.allowed_origin],
      allowMethods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
      allowHeaders: ['Content-Type', 'Authorization'],
    },
  });
  const items = api.root.addResource('items');
  items.addMethod('POST', new apigateway.LambdaIntegration(create));
  items.addMethod('GET', new apigateway.LambdaIntegration(getAll));
  const item = items.addResource('{id}');
  item.addMethod('GET', new apigateway.LambdaIntegration(getOne));
  item.addMethod('PUT', new apigateway.LambdaIntegration(update));
  item.addMethod('DELETE', new apigateway.LambdaIntegration(remove));
  return stack;
}

export function synthesize(configuration) {
  const app = new App({ analyticsReporting: false });
  createStack(app, { configuration });
  return app.synth();
}
